import{_ as o,l as i,o as e,c as l,v as r,p as n,x as t,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"分片键与再平衡","description":"","frontmatter":{"title":"分片键与再平衡","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/shard-key-rebalance.md","filePath":"cs/shard-key-rebalance.md","lastUpdated":1789023840000}'),c={name:"cs/shard-key-rebalance.md"};function E(_,a,f,u,m,T){const s=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="分片键与再平衡" tabindex="-1">分片键与再平衡 <a class="header-anchor" href="#分片键与再平衡" aria-label="Permalink to &quot;分片键与再平衡&quot;">​</a></h1><div class="epigraph"><p>分片键决定行落在哪一故障域；再平衡把键范围从过热节点搬走。选错键，再平衡永远在救热点。</p><footer>—— 据主干 sharding 直觉；DeWitt and Gray 并行库；一致性哈希后课</footer></div><p>复制续在<a href="/cs/replication-lag-rmw">读己之写</a>封口。本课打开分布式数据库：单库分区课已水平切；分片把切放到<strong>多进程多机</strong>，提交与故障域分裂。主干 <a href="/cs/sharding">分片直觉</a> 点到水平切。缺口是键选择与再平衡（rebalance）时的数据搬家与路由。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>键：用户 id 哈希均匀但范围查询打全分片；时间范围利于裁剪但最新分区过热。复合键（租户+时间）折中。缺口是<strong>路由元数据</strong>：谁拥有哪些范围，客户端或协调器查表。再平衡：切范围、拷贝、切流量、删旧——与模式迁移的扩展-收缩同构，加上网络与双写窗口。</p><p>跨分片事务：2PC 或确定性定序，本课不重写协议，只承认键一旦让多数事务跨片，分片失败。</p><p><span class="marginnote">单调主键写入打在最大范围片上，与 IOT 热叶同一病。哈希打散写、毁范围。本课权衡。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先量事务：是否带候选键。再选哈希/范围/目录（lookup）。再平衡尽量在线：新片先跟复制，再改路由，再删。一致性哈希下一课专门减搬家量。</p><p>二级索引全局 vs 本地：全局索引本身要分片，写放大；本地索引查询可能扫所有片。</p>',10)),(e(),n(h,null,{default:t(()=>[p(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20KEY%5B%22%E5%88%86%E7%89%87%E9%94%AE%22%5D%20--%3E%20ROUTE%5B%22%E8%B7%AF%E7%94%B1%E8%A1%A8%22%5D%0A%20%20HOT%5B%22%E7%83%AD%E7%82%B9%E8%8C%83%E5%9B%B4%22%5D%20--%3E%20SPLIT%5B%22%E5%88%87%E5%88%86%E5%B9%B6%E6%8B%B7%E8%B4%9D%22%5D%0A%20%20SPLIT%20--%3E%20CUT%5B%22%E5%88%87%E6%B5%81%E9%87%8F%22%5D%0A%20%20CUT%20--%3E%20DROP%5B%22%E5%88%A0%E6%97%A7%E5%89%AF%E6%9C%AC%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>读己之写：跨片更难，会话要记每片 LSN 或只读主片。计划：优化器有「分片裁剪」，无键谓词 scatter-gather 全片，代价像未分区表×N。</p><p>再平衡时约束：唯一性跨片要全局索引或键包含唯一列。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 shuffle join 算法细节——下一课。也不把分片当 5NF。NewSQL 后课把分片+SQL 打成产品族。</p><p>后课默认：分片键对齐事务边界；再平衡是带路由版本的搬家。shuffle 与 broadcast join：跨片连接如何运数据。</p><p>热点不是硬件不够，是键的时间局部性与切法冲突。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分片键权衡均匀与裁剪；跨片事务比例是失败指标。</li><li>再平衡=拷贝+切路由；元数据要有版本。</li><li>shuffle 与 broadcast join 下一课。</li><li>出处：DeWitt and Gray；主干 sharding；分区课对照。</li></ul>',9))])}const B=o(c,[["render",E]]);export{A as __pageData,B as default};
